mapper.select:
SELECT DISTINCT auxiliary_type
FROM t_auxiliary_item
WHERE is_deleted = 0
AND book_id = #{bookId}
AND tenant_id = #{tenantId}
ORDER BY auxiliary_type ASC

SELECT a.auxiliary_id as auxiliaryId, a.auxiliary_code as auxiliaryCode, a.auxiliary_name as auxiliaryName, a.auxiliary_type as auxiliaryType, a.parent_id as parentId, p.auxiliary_name as parentName, CASE WHEN a.parent_id IS NULL THEN 1 ELSE 2 END as auxiliaryLevel, a.is_leaf as isLeaf, a.is_enabled as isEnabled, a.sort_order as sortOrder, a.book_id as bookId, a.tenant_id as tenantId, a.version as version, a.create_time as createTime, a.update_time as updateTime, a.creator as creator, a.updater as updater FROM t_auxiliary_item a LEFT JOIN t_auxiliary_item p ON a.parent_id = p.auxiliary_id AND p.is_deleted = 0 WHERE a.is_deleted = 0
AND a.book_id = #{param.bookId}
AND a.tenant_id = #{param.tenantId}
AND a.auxiliary_code LIKE CONCAT('%', #{param.auxiliaryCode}, '%')
AND a.auxiliary_name LIKE CONCAT('%', #{param.auxiliaryName}, '%')
AND a.auxiliary_type = #{param.auxiliaryType}
AND a.parent_id = #{param.parentId}
AND a.is_leaf = #{param.isLeaf}
AND a.is_enabled = #{param.isEnabled}
ORDER BY a.auxiliary_type ASC, a.sort_order ASC, a.auxiliary_code ASC

SELECT * FROM t_auxiliary_item
WHERE is_deleted = 0
AND auxiliary_type = #{auxiliaryType}
AND book_id = #{bookId}
ORDER BY sort_order ASC, auxiliary_code ASC

SELECT * FROM t_auxiliary_item
WHERE is_deleted = 0
AND book_id = #{bookId}

    AND parent_id = #{parentId}


    AND parent_id IS NULL

ORDER BY sort_order ASC, auxiliary_code ASC
